const queue = []

function report(endpoint, name, ms) {
  queue.push({ name, ms })
  if (queue.length >= 10) navigator.sendBeacon(endpoint, JSON.stringify(queue.splice(0)))
}

// Times every fetch and XMLHttpRequest the page makes.
export function init({ endpoint }) {
  const nativeFetch = window.fetch
  window.fetch = function (input, options) {
    const start = performance.now()
    return nativeFetch.call(this, input, options).finally(() => report(endpoint, 'fetch', performance.now() - start))
  }

  const open = XMLHttpRequest.prototype.open
  XMLHttpRequest.prototype.open = function (...args) {
    const start = performance.now()
    this.addEventListener('loadend', () => report(endpoint, 'xhr', performance.now() - start))
    return open.apply(this, args)
  }
}
